    26	// Exercise the actual native hook publisher, importer, CLI inventory and TUI.
    27	// Only the owned egg process/transport is a fixture; no account is contacted.
    28	func northstarAttentionHooks(t *testing.T, f *northstarFixture, state, id string, disabled bool) northstarAttentionProvider {
    29		t.Helper()
    30		dir := filepath.Join(state, "eggs", id)
    31		home := filepath.Join(state, "provider-home")
    32		if err := os.MkdirAll(home, 0700); err != nil {
    33			t.Fatal(err)
    34		}
    35		for _, protected := range []string{state, home, filepath.Join(f.home, "mailbox")} {
    36			if !strings.HasPrefix(protected, f.home+string(filepath.Separator)) || strings.HasPrefix(protected, f.work+string(filepath.Separator)) {
    37				t.Fatal("fixture mailbox/state escaped protected HOME")
    38			}
    39		}
    40		northstarWrite(t, filepath.Join(dir, "egg.meta"), "kind=agent\nagent=claude\nprovider_home="+home+"\ncwd="+f.work+"\nisolation=fixture\n", 0600)
    41		northstarWrite(t, filepath.Join(dir, "lifecycle.jsonl"), "", 0600)
    42		providerID := "provider-" + id
    43		args := []string{}
    44		if disabled {
    45			args = []string{"--settings", `{"disableAllHooks":true}`}
    46		}
    47		args, err := egg.ClaudeLifecycleArgs(args, home, id, providerID)
    48		if err != nil {
    49			t.Fatal(err)
    50		}
    51		var settings struct {
    52			Disable bool `json:"disableAllHooks"`
    53			Hooks   map[string][]struct {
    54				Hooks []struct {
    55					Command string `json:"command"`
    56				} `json:"hooks"`
    57			} `json:"hooks"`
    58		}
    59		if err := json.Unmarshal([]byte(args[len(args)-1]), &settings); err != nil {
    60			t.Fatal(err)
    61		}
    62		p := northstarAttentionProvider{f: f, providerID: providerID, commands: make(map[string]string)}
    63		for event, entries := range settings.Hooks {
    64			if len(entries) != 1 || len(entries[0].Hooks) != 1 {
    65				t.Fatalf("unexpected fixture hooks: %s", event)
    66			}
    67			p.commands[event] = entries[0].Hooks[0].Command
    68		}
    69		if disabled && (!settings.Disable || len(p.commands) != 0) {
    70			t.Fatal("disabled hooks were silently installed")
    71		}
    72		return p
    73	}
    74	
    75	func (p northstarAttentionProvider) emit(t *testing.T, event string) {
    76		t.Helper()
    77		command, ok := p.commands[event]
    78		if !ok {
    79			t.Fatalf("native fixture event not installed: %s", event)
    80		}
    81		payload, err := json.Marshal(map[string]any{"session_id": p.providerID, "hook_event_name": event,
    82			"prompt": attentionPrivateContent, "message": attentionPrivateContent, "token": attentionPrivateContent, "error": attentionPrivateContent})
    83		if err != nil {
    84			t.Fatal(err)
    85		}
    86		child := exec.CommandContext(t.Context(), "/bin/sh", "-c", command)
    87		child.Env, child.Dir, child.Stdin = p.f.env, p.f.work, bytes.NewReader(payload)
    88		if output, err := child.CombinedOutput(); err != nil || len(output) != 0 {
    89			t.Fatalf("native hook publisher: %v %q", err, output)
    90		}
    91	}
