    99	func northstarAttentionRefresh(t *testing.T, h *northstarPTY, label string, wantBells int, wants ...string) string {
   100		t.Helper()
   101		text := h.expect(label, h.send("R"), wants...)
   102		// The screen event is readiness evidence, not a fixed sleep. Every emitted
   103		// bell precedes the corresponding render in the actual dashboard loop.
   104		if got := northstarAttentionBells(h); got != wantBells {
   105			t.Fatalf("%s bells=%d, want=%d", label, got, wantBells)
   106		}
   107		return text
   108	}
