   110	func TestNorthstarPTYAttention(t *testing.T) {
   111		t.Run("symlinked-TMPDIR-native-hooks", func(t *testing.T) {
   112			f := northstarNewFixture(t)
   113			binary := northstarBuild(t, f, "stable")
   114			if !strings.HasPrefix(binary, f.tmp+string(filepath.Separator)) {
   115				t.Fatal("built wt bypassed symlinked TMPDIR")
   116			}
   117			if info, err := os.Lstat(f.tmp); err != nil || info.Mode()&os.ModeSymlink == 0 {
   118				t.Fatal("TMPDIR parent was not a test-created symlink")
   119			}
   120			localEgg := northstarStandaloneEgg(t, f, f.local, "same", "local-agent", "working", "ATTENTION_LOCAL_ATTACH_READY")
   121			remoteEgg := northstarStandaloneEgg(t, f, f.remote, "same", "forge-agent", "working", "ATTENTION_REMOTE_ATTACH_READY")
   122			northstarStandaloneEgg(t, f, f.local, "nohooks", "hooks-off", "working", "Allow private text? [Y/n]")
   123			local := northstarAttentionHooks(t, f, f.local, "same", false)
   124			remote := northstarAttentionHooks(t, f, f.remote, "same", false)
   125			northstarAttentionHooks(t, f, f.local, "nohooks", true)
   126			for _, provider := range []northstarAttentionProvider{local, remote} {
   127				provider.emit(t, "SessionStart")
   128				provider.emit(t, "UserPromptSubmit")
   129			}
   130			h := northstarStartPTY(t, f, binary, 120, 32)
   131			h.expect("working and disabled native evidence / no bell", 0, "wt | 3 sessions", "W local-agent", "W forge-agent", "? hooks-off", "U:0", "bell:off")
   132			if northstarAttentionBells(h) != 0 {
   133				t.Fatal("bell was enabled by default")
   134			}
   135			h.expect("instance bell help", h.send("?"), "b: bell off", "unread", "disabled hooks")
   136			h.expect("enable instance bell", h.send("\x1bb"), "Bell on for this dashboard", "bell:on")
   137			h.expect("select exact local provider", h.send("/local-agent\r"), "> W local-agent")
   138			started := time.Now()
   139			local.emit(t, "PermissionRequest")
   140			northstarAttentionRefresh(t, h, "native permission needs input", 1, "B local-agent", "Native provider requested input.")
   141			permissionVisible := time.Since(started)
   142			t.Logf("PermissionRequest to visible native blocked: %s", permissionVisible)
   143			northstarAttentionRefresh(t, h, "repeated permission cursor", 1, "B local-agent")
   144			h.expect("view blocked exact cursor", h.send("i"), "Attention: blocked", "claude_hook", "State cursor: 3", "acknowledgement does not clear blocking")
   145			h.expect("blocked survives viewing", h.send("\x1b"), "B local-agent")
   146			local.emit(t, "Stop")
   147			northstarAttentionRefresh(t, h, "foreground completed / alive provider / unread", 2, "I* local-agent", "U:1", "D:0", "descendants may continue")
   148			if _, alive := eggclient.ReadAliveEggPID(localEgg.dir); !alive {
   149				t.Fatal("foreground completion exited the provider")
   150			}
   151			northstarAttentionRefresh(t, h, "repeated completion cursor", 2, "I* local-agent", "U:1")
   152			h.expect("acknowledge local completion", h.send("i"), "Details: local:same", "State cursor: 4", "Foreground response completed", "U:0")
   153			h.expect("return after exact acknowledgement", h.send("\x1b"), "I local-agent", "U:0")
   154			h.expect("filter disabled hooks", h.send("/\x15hooks-off\r"), "> ? hooks-off")
   155			h.expect("unknown evidence explains itself", h.send("i"), "Attention: unknown", "unsupported", "missing, unknown or hooks are disabled", "no screen inference")
   156			h.expect("clear disabled filter", h.send("\x1b/\x15\r"), "I local-agent", "W forge-agent")
   157			// Identical session IDs belong to separate machines and hook spools.
   158			local.emit(t, "UserPromptSubmit")
   159			local.emit(t, "Stop")
   160			remote.emit(t, "Stop")
   161			northstarAttentionRefresh(t, h, "two same IDs / two unread results", 4, "I* local-agent", "I* forge-agent", "U:2")
   162			h.expect("select only local result", h.send("/local-agent\r"), "> I* local-agent")
   163			h.expect("ack only local result", h.send("i"), "Details: local:same", "U:1")
   164			h.expect("select forge after local acknowledgement", h.send("\x1b/\x15forge-agent\r"), "> I* forge-agent", "U:1")
   165			h.expect("attach exact remote result", h.send("\r"), "ATTENTION_REMOTE_ATTACH_READY")
   166			select {
   167			case id := <-remoteEgg.attached:
   168				if id != "same" {
   169					t.Fatal(id)
   170				}
   171			case <-time.After(time.Second):
   172				t.Fatal("remote exact-ID attachment did not execute")
   173			}
   174			h.expect("remote detach acknowledges captured completion", h.send("\x02q"), "I forge-agent", "U:0")
   175			if northstarAttentionBells(h) != 4 {
   176				t.Fatal("attach/detach replayed a completion alert")
   177			}
   178			h.expect("restore all rows", h.send("/\x15\r"), "I local-agent", "I forge-agent")
   179			remote.emit(t, "UserPromptSubmit")
   180			remote.emit(t, "Stop")
   181			northstarAttentionRefresh(t, h, "new remote completion", 5, "I* forge-agent", "U:1")
   182			northstarWrite(t, filepath.Join(f.home, "forge-offline"), "fixture offline", 0600)
   183			northstarAttentionRefresh(t, h, "stale machine retains visual unread", 5, "cached rows stale", "I* forge-agent", "U:1")
   184			if err := os.Remove(filepath.Join(f.home, "forge-offline")); err != nil {
   185				t.Fatal(err)
   186			}
   187			h.waitScreen("reconnect without repeated cursor bell", h.send("R"), func(screen string) bool {
   188				return strings.Contains(screen, "I* forge-agent") && strings.Contains(screen, "U:1") && !strings.Contains(screen, "cached rows stale")
   189			})
   190			if northstarAttentionBells(h) != 5 {
   191				t.Fatal("reconnect replayed an alert")
   192			}
   193			h.expect("disable bell keeps visual attention", h.send("b"), "bell:off")
   194			local.emit(t, "PermissionRequest")
   195			northstarAttentionRefresh(t, h, "disabled bell still shows blocked", 5, "B local-agent", "U:1")
   196			// The footer advertises ! attention even before the filter is applied.
   197			// Inventory refreshes can redraw that old view after send, so wait for
   198			// the filtered header and complete rows in the same rendered snapshot.
   199			h.waitScreen("attention filter excludes unknown", h.send("!"), func(screen string) bool {
   200				return strings.Contains(screen, "[All ! attention]") &&
   201					strings.Contains(screen, "B local-agent") && strings.Contains(screen, "I* forge-agent") &&
   202					!strings.Contains(screen, "hooks-off")
   203			})
   204			h.exit("q")
   205			fresh := northstarStartPTY(t, f, binary, 120, 32)
   206			// Storyboard 03/card-2: "Unread must be based on new output and a durable read cursor".
   207			// Reopening the same viewer does not acknowledge the remote completion.
   208			fresh.expect("same viewer reopen / durable remote unread / known blocked", 0, "B local-agent", "I* forge-agent", "U:1", "bell:off")
   209			fresh.exit("q")
   210			for _, pty := range []*northstarPTY{h, fresh} {
   211				pty.mu.Lock()
   212				private := bytes.Contains(pty.transcript.Bytes(), []byte(attentionPrivateContent))
   213				pty.mu.Unlock()
   214				if private {
   215					t.Fatal("alert/list/details exposed hook payload or transcript content")
   216				}
   217			}
   218			northstarWrite(t, filepath.Join(f.evidence, "attention-timing.txt"), fmt.Sprintf("permission_to_visible=%s; final_bells=5; two_machine_same_id=true\n", permissionVisible), 0600)
   219		})
   220	}
