   411	func storyboardFleet(t *testing.T) (*northstarFixture, string, *northstarEgg, *northstarEgg, *northstarPTY) {
   412		t.Helper()
   413		f, binary := storyboardFixture(t)
   414		local := northstarStandaloneEgg(t, f, f.local, "same", "coordinator", "working", "LOCAL_EXACT")
   415		remote := northstarStandaloneEgg(t, f, f.remote, "same", "coordinator", "needs_input", "FORGE_EXACT")
   416		h := northstarStartPTY(t, f, binary, 140, 40)
   417		h.expect("grouped machines", 0, "local", "forge", "coordinator", "work", "W coordinator", "B coordinator")
   418		return f, binary, local, remote, h
   419	}
