   478	func storyboardOffline(t *testing.T) {
   479		f, _, local, remote, h := storyboardFleet(t)
   480		northstarWrite(t, filepath.Join(f.home, "forge-offline"), "offline", 0600)
   481		h.expect("stale remote inventory", h.send("R"), "forge  offline", "last success", "stale", "coordinator")
   482		h.expect("local remains available", h.send("/local\r"), "> W coordinator")
   483		h.expect("local attach while forge offline", h.send("\r"), "LOCAL_EXACT")
   484		h.expect("local detach", h.send("\x02q"), "> W coordinator")
   485		h.expect("select stale exact route", h.send("/\x15forge\r"), "stale", "B coordinator")
   486		h.expect("stale attach denied", h.send("\r"), "cannot validate")
   487		h.exit("q")
   488		if len(remote.attached) != 0 || local.killed.Load() != 0 || remote.killed.Load() != 0 {
