    57			identity.generation = 0
    58			profile := s.attentionProfiles[name]
    59			if !profile.active || profile.identity != identity {
    60				profile = attentionProfile{identity: identity, generation: profile.generation + 1, active: true}
    61				s.attentionProfiles[name] = profile
    62			}
    63			m := s.machines[name]
    64			if m.err != "" {
    65				continue
    66			}
    67			for _, session := range m.sessions {
