   108	func (s *state) attentionFor(r row) string {
   109		// Older compatible inventories omit the additive lifecycle fields. Their
   110		// blocked/failed status remains useful visual evidence, but supplies no
   111		// cursor for a bell or a completion inference.
   112		if r.StateSource == "" && r.State == "" && (r.Status == "blocked" || r.Status == "failed") {
   113			return r.Status
   114		}
   115		if !nativeSource(r.StateSource) || r.StateCursor <= 0 || r.State == "unknown" || r.State == "" {
   116			if r.StateSource == "egg_process" && (r.State == "failed" || r.State == "stopped") {
   117				return "failed"
   118			}
   119			return "unknown"
   120		}
   121		switch r.State {
   122		case "needs_input":
   123			return "blocked"
   124		case "failed", "stopped":
   125			return "failed"
   126		}
   127		record := s.attention[r.identity]
   128		if record.completion > record.seen {
   129			return "unread"
   130		}
   131		if r.State == "working" || r.State == "starting" {
   132			return "active"
   133		}
   134		return "none"
   135	}
