   137	func (s *state) acknowledge(r row) {
   138		record, ok := s.attention[r.identity]
   139		if ok {
   140			// The captured view acknowledges exactly what it showed, even if a
   141			// newer completion arrived before this key/action was processed.
   142			record.seen = max(record.seen, min(r.completion, record.completion))
   143			s.attention[r.identity] = record
   144		}
   145	}
