    29	func (s *state) attentionIdentity(name, id string) attentionIdentity {
    30		identity := attentionIdentity{machine: name, session: id, generation: s.attentionProfiles[name].generation}
    31		if name == "local" {
    32			identity.localDir = s.localDir
    33		} else {
    34			identity.profile = s.remotes[name]
    35		}
    36		return identity
    37	}
