    41	// Called by reconciliation after inventory application. Failed queries retain
    42	// their visual snapshot but cannot advance cursors or generate alerts.
    43	func (s *state) observeAttention() {
    44		if s.attention == nil {
    45			s.attention = make(map[attentionIdentity]attentionRecord)
    46		}
    47		if s.attentionProfiles == nil {
    48			s.attentionProfiles = make(map[string]attentionProfile)
    49		}
    50		for name, profile := range s.attentionProfiles {
    51			if _, ok := s.machines[name]; !ok {
    52				profile.active = false
    53				s.attentionProfiles[name] = profile
    54			}
    55		}
    56		for _, name := range s.machineNames() {
    57			identity := s.attentionIdentity(name, "")
    58			identity.generation = 0
    59			profile := s.attentionProfiles[name]
    60			if !profile.active || profile.identity != identity {
    61				profile = attentionProfile{identity: identity, generation: profile.generation + 1, active: true}
    62				s.attentionProfiles[name] = profile
    63			}
    64			m := s.machines[name]
    65			if m.err != "" {
    66				continue
    67			}
    68			for _, session := range m.sessions {
    69				key := s.attentionIdentity(name, session.ID)
    70				record, known := s.attention[key]
    71				if !known && s.attentionStore != nil && key.generation == 1 {
    72					var err error
    73					record, known, err = s.attentionStore.load(key)
    74					if err != nil {
    75						s.message = "Cannot read navigator cursors: " + err.Error()
    76						continue
    77					}
    78				}
    79				previous := record
    80				if session.StateCursor < record.cursor {
    81					continue
    82				}
    83				qualifying := false
    84				message := ""
    85				if nativeSource(session.StateSource) && session.StateCursor > 0 {
    86					if session.State == "needs_input" && session.StateCursor > record.blocked {
    87						record.blocked = session.StateCursor
    88						qualifying, message = true, "Native provider requested input."
    89					}
    90					if session.CompletionCursor > record.completion && session.CompletionCursor <= session.StateCursor {
    91						record.completion = session.CompletionCursor
    92						qualifying, message = true, "New foreground response; provider or descendants may continue."
    93					}
    94				}
    95				record.cursor = max(record.cursor, session.StateCursor)
    96				if !known {
    97					// Baseline historical completions; known input requests remain
    98					// visibly blocked without a startup storm of audible alerts.
    99					record.seen = record.completion
   100				}
   101				attached := s.attached != nil && *s.attached == key
   102				if attached {
   103					record.seen = record.completion
   104				}
   105				s.attention[key] = record
   106				if !known || previous != record {
   107					s.persistAttention(key, record, !known && key.generation > 1)
   108				}
   109				if known && qualifying && !attached {
   110					if s.bell {
   111						s.pendingBells++
   112					}
   113					if !s.busy {
   114						s.message = message
   115					}
   116				}
   117			}
   118		}
   119	}
