   121	func (s *state) attentionFor(r row) string {
   122		// Older compatible inventories omit the additive lifecycle fields. Their
   123		// blocked/failed status remains useful visual evidence, but supplies no
   124		// cursor for a bell or a completion inference.
   125		if r.StateSource == "" && r.State == "" && (r.Status == "blocked" || r.Status == "failed") {
   126			return r.Status
   127		}
   128		if !nativeSource(r.StateSource) || r.StateCursor <= 0 || r.State == "unknown" || r.State == "" {
   129			if r.StateSource == "egg_process" && (r.State == "failed" || r.State == "stopped") {
   130				return "failed"
   131			}
   132			return "unknown"
   133		}
   134		switch r.State {
   135		case "needs_input":
   136			return "blocked"
   137		case "failed", "stopped":
   138			return "failed"
   139		}
   140		record := s.attention[r.identity]
   141		if record.completion > record.seen {
   142			return "unread"
   143		}
   144		if r.State == "working" || r.State == "starting" {
   145			return "active"
   146		}
   147		return "none"
   148	}
