   150	func (s *state) acknowledge(r row) {
   151		record, ok := s.attention[r.identity]
   152		if ok {
   153			// The captured view acknowledges exactly what it showed, even if a
   154			// newer completion arrived before this key/action was processed.
   155			record.seen = max(record.seen, min(r.completion, record.completion))
   156			s.attention[r.identity] = record
   157			s.persistAttention(r.identity, record, false)
   158		}
   159	}
   160	
   161	func (s *state) persistAttention(key attentionIdentity, record attentionRecord, reset bool) {
   162		if s.attentionStore != nil && key == s.attentionIdentity(key.machine, key.session) {
   163			if err := s.attentionStore.save(key, record, reset); err != nil {
   164				s.message = "Cannot save navigator cursors: " + err.Error()
   165			}
   166		}
   167	}
