     3	import (
     4		"crypto/sha256"
     5		"database/sql"
     6		"encoding/json"
     7		"errors"
     8		"fmt"
     9		"os"
    10		"path/filepath"
    11	
    12		"github.com/ehrlich-b/wingthing/internal/config"
    13		_ "modernc.org/sqlite"
    14	)
    15	
    16	// The state directory belongs to the local OS viewer. Store only lifecycle
    17	// cursors, never provider output, and never use these receipts as authority.
    18	type attentionStore struct{ *sql.DB }
    19	
    20	func openAttentionStore(dir string) (*attentionStore, error) {
    21		if err := os.MkdirAll(dir, 0700); err != nil {
    22			return nil, err
    23		}
    24		path := filepath.Join(dir, "navigator-attention.db")
    25		file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0600)
    26		if err != nil {
    27			return nil, err
    28		}
    29		if err := file.Close(); err != nil {
    30			return nil, err
    31		}
    32		db, err := sql.Open("sqlite", path)
    33		if err != nil {
    34			return nil, err
    35		}
    36		db.SetMaxOpenConns(1)
    37		for _, statement := range []string{
    38			"PRAGMA busy_timeout=3000",
    39			`CREATE TABLE IF NOT EXISTS read_cursors (
    40			 identity TEXT PRIMARY KEY, completion INTEGER NOT NULL,
    41			 seen INTEGER NOT NULL, blocked INTEGER NOT NULL, cursor INTEGER NOT NULL)`,
    42		} {
    43			if _, err := db.Exec(statement); err != nil {
    44				db.Close()
    45				return nil, err
    46			}
    47		}
    48		return &attentionStore{db}, nil
    49	}
    50	
    51	func attentionKey(key attentionIdentity) string {
    52		// Runtime generations prevent old on-screen acknowledgements; reopening
    53		// the same route must find its durable cursor irrespective of generation.
    54		wire, _ := json.Marshal(struct {
    55			Machine, Session, LocalDir string
    56			Profile                    config.Remote
    57		}{key.machine, key.session, key.localDir, key.profile})
    58		return fmt.Sprintf("%x", sha256.Sum256(wire))
    59	}
    60	
    61	func (db *attentionStore) load(key attentionIdentity) (attentionRecord, bool, error) {
    62		var r attentionRecord
    63		err := db.QueryRow("SELECT completion, seen, blocked, cursor FROM read_cursors WHERE identity = ?", attentionKey(key)).Scan(&r.completion, &r.seen, &r.blocked, &r.cursor)
    64		if errors.Is(err, sql.ErrNoRows) {
    65			return r, false, nil
    66		}
    67		return r, err == nil, err
    68	}
    69	
    70	func (db *attentionStore) save(key attentionIdentity, r attentionRecord, reset bool) error {
    71		statement := `INSERT INTO read_cursors VALUES (?, ?, ?, ?, ?)
    72		 ON CONFLICT(identity) DO UPDATE SET
    73		 completion=max(completion, excluded.completion), seen=max(seen, excluded.seen),
    74		 blocked=max(blocked, excluded.blocked), cursor=max(cursor, excluded.cursor)`
    75		if reset {
    76			statement = "INSERT OR REPLACE INTO read_cursors VALUES (?, ?, ?, ?, ?)"
    77		}
    78		// Atomic monotonic merges keep an older navigator from overwriting a
    79		// newer observation or acknowledgement made by another navigator.
    80		_, err := db.Exec(statement, attentionKey(key), r.completion, r.seen, r.blocked, r.cursor)
    81		return err
    82	}
