    11	func TestAttentionDurableViewerRoutesAndAcknowledgement(t *testing.T) {
    12		dir := t.TempDir()
    13		open := func() *state {
    14			db, err := openAttentionStore(dir)
    15			if err != nil {
    16				t.Fatal(err)
    17			}
    18			t.Cleanup(func() { db.Close() })
    19			return &state{localDir: dir, attentionStore: db,
    20				machines: map[string]machine{"local": {}, "forge": {}},
    21				remotes:  map[string]config.Remote{"forge": {SSHTarget: "original", WingthingDir: "/remote"}}}
    22		}
    23		first := open()
    24		for _, name := range []string{"local", "forge"} {
    25			attentionApply(first, name, attentionSession("working", 1, 0))
    26			attentionApply(first, name, attentionSession("completed", 2, 2))
    27		}
    28		first.acknowledge(first.rows()[0])
    29		second := open()
    30		for _, name := range []string{"local", "forge"} {
    31			attentionApply(second, name, attentionSession("completed", 2, 2))
    32		}
    33		if second.rows()[0].attention != "none" || second.rows()[1].attention != "unread" {
    34			t.Fatal("reopen lost route-specific read cursors")
    35		}
    36		shown := second.rows()[1]
    37		attentionApply(first, "forge", attentionSession("completed", 3, 3))
    38		second.acknowledge(shown)
    39		third := open()
    40		attentionApply(third, "forge", attentionSession("completed", 3, 3))
    41		if third.rows()[0].attention != "unread" {
    42			t.Fatal("older viewer erased a newer unread completion")
    43		}
    44		third.acknowledge(third.rows()[0])
    45		fourth := open()
    46		attentionApply(fourth, "forge", attentionSession("completed", 3, 3))
    47		if fourth.rows()[0].attention != "none" {
    48			t.Fatal("acknowledgement did not survive reopen")
    49		}
    50		old := first.rows()[1]
    51		fourth.remotes["forge"] = config.Remote{SSHTarget: "replacement", WingthingDir: "/remote"}
    52		attentionApply(fourth, "forge", attentionSession("working", 1, 0))
    53		fourth.remotes["forge"] = first.remotes["forge"]
    54		attentionApply(fourth, "forge", attentionSession("working", 1, 0))
    55		attentionApply(fourth, "forge", attentionSession("completed", 2, 2))
    56		// An old captured row may remain in a different generation's records.
    57		fourth.attention[old.identity] = first.attention[old.identity]
    58		fourth.acknowledge(old)
    59		fifth := open()
    60		attentionApply(fifth, "forge", attentionSession("completed", 2, 2))
    61		if fifth.rows()[0].attention != "unread" {
    62			t.Fatal("old profile generation acknowledged a replacement across reopen")
    63		}
    64		fourth.remotes["forge"] = config.Remote{SSHTarget: "replacement", WingthingDir: "/remote"}
    65		attentionApply(fourth, "forge", attentionSession("completed", 4, 4))
    66		if fourth.rows()[0].attention != "none" {
    67			t.Fatal("replacement inherited another route's unread state")
    68		}
    69		info, err := os.Stat(filepath.Join(dir, "navigator-attention.db"))
    70		if err != nil || info.Mode().Perm() != 0600 {
    71			t.Fatal("read cursors are not owner-only", info, err)
    72		}
    73	}
